    setStore((prev) => {
      const next: AppStore = {
        version: 1,
        tasks: [],
        focusLog: [],
        timer: prev.timer,
        theme: prev.theme,
      };
      saveStore(next);
      clearDemoSeeded();
      try {
        localStorage.removeItem("sigil-focus-demo-dismissed");
