        title: task.title,
        description: task.description,
        priority: task.priority,
        labels: task.labels,
        storyPoints: task.storyPoints,
        column: task.column,
      });
      return task;
    },
    [commit],
  );

  const updateTask: AppApi["updateTask"] = useCallback(
    (id, patch) => {
      commit((prev) => ({
        ...prev,
        tasks: prev.tasks.map((t) =>
          t.id === id ? { ...t, ...patch, updatedAt: new Date().toISOString() } : t,
