import { AppShell } from "@/components/sigil/app-shell";

/**
 * The live-demo route. `searchParams` is read HERE, server-side, so the
 * `?embed=1` flag reaches the client tree as a PROP — the server render and
 * the hydration render agree and React #418 never fires (the standalone app
 * learned this the hard way: reading window.location.search inside a
 * useState initializer made every ?embed=1 visit a hydration mismatch).
 *
 * Reading searchParams makes this route dynamic (ƒ) — the landing page
 * itself stays fully static.
 */
export default async function DemoPage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const params = await searchParams;
  const raw = Array.isArray(params.embed) ? params.embed[0] : params.embed;
  const initialEmbed = raw === "1" || raw === "true";
  return <AppShell initialEmbed={initialEmbed} />;
}

"use client";

import { useEffect, useState } from "react";
import type { ColumnId, Task } from "@/lib/sigil/types";
import { COLUMNS } from "@/lib/sigil/types";
import { TaskCard } from "./task-card";

interface BoardProps {
  tasks: Task[];
  activeColumn: ColumnId;
  onColumnClick: (c: ColumnId) => void;
  onNewTask: () => void;
  onEdit: (t: Task) => void;
  onDelete: (id: string) => void;
  onMove: (id: string, column: ColumnId) => void;
  onLogFocus: (taskId: string) => void;
}

export function Board({
  tasks,
  activeColumn,
  onColumnClick,
  onNewTask,
  onEdit,
  onDelete,
  onMove,
  onLogFocus,
}: BoardProps) {
  const tasksByColumn = (col: ColumnId) => tasks.filter((t) => t.column === col);
  // Active column is driven by keyboard shortcuts (1-4) and tab clicks.
  // On mobile only the active column is rendered; on desktop all are shown.
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const mq = window.matchMedia("(max-width: 767px)");
    const update = () => setIsMobile(mq.matches);
    update();
    mq.addEventListener("change", update);
    return () => mq.removeEventListener("change", update);
  }, []);

  const shown = isMobile
    ? COLUMNS.filter((c) => c.id === activeColumn)
    : [...COLUMNS];

  return (
    <section aria-label="Kanban board" className="space-y-3">
      {/* Mobile column tabs */}
      <div
        role="tablist"
        aria-label="Board columns"
        className="flex gap-1 overflow-x-auto md:hidden"
      >
        {COLUMNS.map((c, i) => (
          <button
            key={c.id}
            role="tab"
            aria-selected={activeColumn === c.id}
            onClick={() => onColumnClick(c.id)}
            className={`whitespace-nowrap rounded-t-lg border-b-2 px-3 py-1.5 text-sm font-medium transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-sf-accent ${
              activeColumn === c.id
                ? "border-sf-accent text-sf"
                : "border-transparent text-sf-dim"
            }`}
          >
            <span className="sr-only">
              Jump to {c.title} column (key {i + 1})
            </span>
            {c.title}{" "}
            <span className="text-xs text-sf-dim">
              ({tasksByColumn(c.id).length})
            </span>
          </button>
        ))}
      </div>

      <div
        role="tabpanel"
        aria-label="Board columns"
        className={`grid items-stretch gap-3 ${
          isMobile ? "grid-cols-1" : "grid-cols-1 md:grid-cols-2 lg:grid-cols-4"
        }`}
      >
        {shown.map((col) => (
          <Column
            key={col.id}
            column={col.id}
            title={col.title}
            tasks={tasksByColumn(col.id)}
            active={activeColumn === col.id}
            onColumnClick={onColumnClick}
            onNewTask={onNewTask}
            onEdit={onEdit}
            onDelete={onDelete}
            onMove={onMove}
            onLogFocus={onLogFocus}
          />
        ))}
      </div>
    </section>
  );
}

interface ColumnProps {
  column: ColumnId;
  title: string;
  tasks: Task[];
  active: boolean;
  onColumnClick: (c: ColumnId) => void;
  onNewTask: () => void;
  onEdit: (t: Task) => void;
  onDelete: (id: string) => void;
  onMove: (id: string, column: ColumnId) => void;
  onLogFocus: (taskId: string) => void;
}

function Column({
  column,
  title,
  tasks,
  active,
  onColumnClick,
  onNewTask,
  onEdit,
  onDelete,
  onMove,
  onLogFocus,
}: ColumnProps) {
  const [dragOver, setDragOver] = useState(false);

  return (
    <div
      role="region"
      aria-label={`${title} column, ${tasks.length} tasks`}
      tabIndex={0}
      onDragOver={(e) => {
        e.preventDefault();
        setDragOver(true);
      }}
      onDragLeave={() => setDragOver(false)}
      onDrop={(e) => {
        e.preventDefault();
        setDragOver(false);
        const id = e.dataTransfer.getData("text/task-id");
        if (id) onMove(id, column);
      }}
      onClick={() => onColumnClick(column)}
      className={`flex h-full flex-col rounded-xl border bg-sf-surface p-3 transition-colors ${
        dragOver ? "border-sf-accent" : active ? "border-sf-accent/40" : "border-sf-border"
      }`}
    >
      <div className="mb-2 flex items-center justify-between">
        <h2 className="text-sm font-semibold uppercase tracking-wider text-sf-dim">
          {title}
          <span className="ml-2 text-xs font-normal text-sf-dim">{tasks.length}</span>
        </h2>
        <button
          type="button"
          onClick={(e) => {
            e.stopPropagation();
            onColumnClick(column);
            onNewTask();
          }}
          aria-label={`Add task to ${title}`}
          className="rounded px-2 text-lg leading-none text-sf-dim hover:bg-sf-surface-2 hover:text-sf focus-visible:outline focus-visible:outline-2 focus-visible:outline-sf-accent"
        >
          +
        </button>
      </div>

      <ul role="list" className="flex flex-1 flex-col gap-2">
        {tasks.length === 0 && (
          <li className="px-1 py-3 text-center text-xs text-sf-dim/70">
            Drop tasks here or press <kbd className="rounded border border-sf-border px-1 font-mono">n</kbd>
          </li>
        )}
        {tasks.map((task) => (
          <li key={task.id} onClick={(e) => e.stopPropagation()}>
            <TaskCard
              task={task}
              onEdit={() => onEdit(task)}
              onDelete={() => onDelete(task.id)}
              onMoveTo={(col) => onMove(task.id, col)}
              onLogFocus={() => onLogFocus(task.id)}
            />
          </li>
        ))}
      </ul>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useAppStore } from "./use-app-store";
import { type ColumnId, type Task, type TaskDraft } from "@/lib/sigil/types";
import { Header } from "./header";
import { Board } from "./board";
import { CardEditor } from "./card-editor";
import { FocusTimer } from "./focus-timer";
import { StatsView } from "./stats-view";
import { TemplatesPanel } from "./templates-panel";

type View = "board" | "focus" | "stats";
export type { View };

export function AppShell({ initialEmbed }: { initialEmbed?: boolean } = {}) {
  const app = useAppStore({ initialEmbed });
  const { store, hydrated, embed, demoBadgeVisible, dismissDemoBadge, resetBoard } = app;
  const [view, setView] = useState<View>("board");
  const [activeColumn, setActiveColumn] = useState<ColumnId>("backlog");
  const [search, setSearch] = useState("");
  const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null);
  const [editorOpen, setEditorOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [toast, setToast] = useState<string | null>(null);
  const [resetOpen, setResetOpen] = useState(false);
  const toastTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const notify = useCallback((msg: string) => {
    setToast(msg);
    if (toastTimerRef.current) clearTimeout(toastTimerRef.current);
    toastTimerRef.current = setTimeout(() => setToast(null), 2600);
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    if (!hydrated) return;
    const onKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const typing =
        target &&
        (target.tagName === "INPUT" ||
          target.tagName === "TEXTAREA" ||
          target.tagName === "SELECT" ||
          target.isContentEditable);
      if (typing) {
        if (e.key === "Escape") (target as HTMLElement).blur();
        return;
      }
      switch (e.key) {
        case "n":
        case "N":
          e.preventDefault();
          setEditingTask(null);
          setEditorOpen(true);
          break;
        case "/":
          e.preventDefault();
          document.getElementById("search-input")?.focus();
          break;
        case "1":
          setActiveColumn("backlog");
          break;
        case "2":
          setActiveColumn("doing");
          break;
        case "3":
          setActiveColumn("review");
          break;
        case "4":
          setActiveColumn("done");
          break;
        case "t":
        case "T":
          app.toggleTheme();
          break;
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [hydrated, app]);

  const filteredTasks = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return store.tasks;
    return store.tasks.filter(
      (t) =>
        t.title.toLowerCase().includes(q) ||
        t.description.toLowerCase().includes(q) ||
        t.labels.some((l) => l.toLowerCase().includes(q)),
    );
  }, [store.tasks, search]);

  const openNew = useCallback(() => {
    setEditingTask(null);
    setEditorOpen(true);
  }, []);

  const openEdit = useCallback((task: Task) => {
    setEditingTask(task);
    setEditorOpen(true);
  }, []);

  const handleSave = useCallback(
    (draft: TaskDraft) => {
      if (editingTask) {
        app.updateTask(editingTask.id, { ...draft, column: editingTask.column });
        notify("Task updated");
      } else {
        app.addTask(draft);
        notify("Task added");
      }
      setEditorOpen(false);
      setEditingTask(null);
    },
    [app, editingTask, notify],
  );

  const handleMove = useCallback(
    (id: string, column: ColumnId) => {
      app.moveTaskTo(id, column);
      if (column === "done") notify("Task completed 🎉");
    },
    [app, notify],
  );

  const handleReset = useCallback(() => {
    resetBoard();
    setResetOpen(false);
    setView("board");
    notify("Board reset");
  }, [resetBoard, notify]);

  return (
    <div className="flex min-h-screen flex-col px-3 sm:px-6">
      {!embed && (
        <Header
          theme={store.theme}
          onToggleTheme={() => app.toggleTheme()}
          view={view}
          onView={setView}
          search={search}
          onSearch={setSearch}
        />
      )}

      {/* Demo badge — dismissible, only when demo data was seeded */}
      {demoBadgeVisible && !embed && (
        <div
          role="status"
          aria-live="polite"
          className="flex items-center justify-between rounded-lg border border-sf-accent/30 bg-sf-accent/10 px-3 py-1.5 text-xs text-sf"
        >
          <span>
            <span aria-hidden>◈</span> Demo data loaded — explore freely. Your changes are saved locally.
          </span>
          <button
            type="button"
            onClick={dismissDemoBadge}
            aria-label="Dismiss demo data notice"
            className="ml-3 rounded px-1.5 text-sf-dim hover:text-sf focus-visible:outline focus-visible:outline-2 focus-visible:outline-sf-accent"
          >
            ✕
          </button>
        </div>
      )}

      <main className="mx-auto w-full flex-1 py-3">
        {view === "board" && (
          <Board
            tasks={filteredTasks}
            activeColumn={activeColumn}
            onColumnClick={setActiveColumn}
            onNewTask={openNew}
            onEdit={openEdit}
            onDelete={(id) => {
              app.deleteTask(id);
              notify("Task deleted");
            }}
            onMove={handleMove}
            onLogFocus={(taskId) => {
              setSelectedTaskId(taskId);
              setView("focus");
            }}
          />
        )}

        {view === "focus" && (
          <FocusTimer
            tasks={store.tasks}
            timer={store.timer}
            onTimer={app.setTimer}
            selectedTaskId={selectedTaskId}
            onSelectTask={setSelectedTaskId}
            onSessionComplete={app.logFocus}
          />
        )}

        {view === "stats" && (
          <StatsView
            tasks={store.tasks}
            focusLog={store.focusLog}
            onReset={embed ? undefined : handleReset}
          />
        )}
      </main>

      {editorOpen && (
        <CardEditor
          task={editingTask}
          defaultColumn={activeColumn}
          onClose={() => {
            setEditorOpen(false);
            setEditingTask(null);
          }}
          onSave={handleSave}
        />
      )}

      {!embed && (
        <TemplatesPanel
          onApply={(id, drafts) => {
            app.applyTemplate(id, drafts);
            setView("board");
            notify(`Template "${id}" applied`);
          }}
        />
      )}

      {toast && (
        <div
          role="status"
          aria-live="polite"
          className="fixed bottom-4 left-1/2 z-50 -translate-x-1/2 rounded-full border border-sf-border bg-sf-surface px-4 py-2 text-sm text-sf shadow-lg"
        >
          {toast}
        </div>
      )}

      {!embed && (
        <footer className="border-t border-sf-border py-4">
          <div className="mx-auto flex max-w-7xl flex-wrap items-center justify-center gap-x-4 gap-y-2 text-xs text-sf-dim">
            <span>Local-first · syncs to API when available</span>
            <span className="flex items-center gap-3">
              <span className="flex items-center gap-1">
                <kbd className="rounded border border-sf-border bg-sf-surface-2 px-1.5 py-0.5 font-mono text-[11px] text-sf">n</kbd>
                new
              </span>
              <span className="flex items-center gap-1">
                <kbd className="rounded border border-sf-border bg-sf-surface-2 px-1.5 py-0.5 font-mono text-[11px] text-sf">/</kbd>
                search
              </span>
              <span className="flex items-center gap-1">
                <kbd className="rounded border border-sf-border bg-sf-surface-2 px-1.5 py-0.5 font-mono text-[11px] text-sf">1–4</kbd>
                columns
              </span>
              <span className="flex items-center gap-1">
                <kbd className="rounded border border-sf-border bg-sf-surface-2 px-1.5 py-0.5 font-mono text-[11px] text-sf">t</kbd>
                theme
              </span>
            </span>
          </div>
        </footer>
      )}
    </div>
  );
}

